body{font-family:"Noto Sans Display",Arial,Helv,Helvetica,Verdana,sans-serif;color:#191919;background:#fff}
.bt-header{background:#fff;border-bottom:1px solid #e6e6e6}
.bt-main-nav a{color:#191919;text-decoration:none;font-weight:600}
.bt-main-nav a:hover,.bt-main-nav a:focus{color:#ff7100}
.bt-teaser-headline{font-family:"Noto Serif",Georgia,"Times New Roman",Times,serif;font-weight:700}
.bt-btn-primary{background-color:#ff7100;color:#fff;border:none;padding:.6rem 1.2rem}
.bt-btn-primary:hover{background-color:#e6660a}
.bt-module-row{background:#f6f6f6;padding:2rem 0}
.bt-footer{background:#191919;color:#f6f6f6}
.bt-footer a{color:#e6e6e6}
.bt-alert-danger{color:#a94442;background-color:#f2dede}

body{font-family:BundesSansWeb,Calibri,Verdana,Arial,Helvetica,sans-serif;color:#111314;background:#fff}
h1,h2,h3{font-family:"BundesSerifWeb",Cambria,Georgia,"Times New Roman",serif}
.header-main{background:#fff;border-bottom:3px solid #004b76}
.main-nav a{color:#111314;font-family:"Fira Sans",Arial,Helvetica,sans-serif}
.main-nav a:hover{color:#0071ad}
.btn-primary{background-color:#0071ad;color:#fff;border-radius:2px;padding:.5rem 1.25rem}
.btn-primary:hover{background-color:#004b76}
.teaser-card{background:#eeeff1;border-left:4px solid #0071ad}
.tag--rot{background-color:#c0003c;color:#fff}
.tag--gruen{background-color:#00854a;color:#fff}
.cookie-banner{background:#111314;color:#fff}

body{font-family:"bundessansweb","Droid Sans",Arial,"Helvetica Neue",Helvetica,sans-serif;color:#333;background:#fff}
